var t=`1383-cassava-pone`;var i=`world-1383`;var s=`GY`;var n=`south-america`;var o=8;var r=122;var u={en:`Cassava Pone`,ua:`Пиріг із маніоку`};var d={en:`Cassava Pone is a dish from Guyana featuring cassava root, coconut, coconut milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Пиріг із маніоку, страва кухні країни Гаяна з такими основними складниками: маніок, кокос, кокосове молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:17,i:[[`cassava-root`,720,`g`],[`coconut`,250,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:11,i:[[`dark-brown-sugar`,210,`g`],[`coconut-milk`,330,`ml`],[`unsalted-butter`,75,`g`],[`ground-cinnamon`,5,`g`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:9,i:[]},{en:`Bake grated cassava thoroughly until the center is fully set, with no raw wet cassava remaining; use properly peeled food-grade cassava root.`,ua:`Ретельно запікайте натертий маніок до повної готовності середини, без сирих вологих ділянок; використовуйте правильно очищений харчовий корінь.`,t:[`baking`],m:60,i:[]},{en:`Serve the dish at the intended temperature and garnish as needed with previously prepared ingredients.`,ua:`Подавайте страву за відповідної температури й прикрашайте раніше підготовленими складниками.`,t:[`garnishing`],m:25,i:[]}];var l={slug:t,id:i,country:`GY`,region:n,servings:8,minutes:122,title:u,text:d,steps:g};export{s as country,l as default,i as id,r as minutes,n as region,o as servings,t as slug,g as steps,d as text,u as title};